.libPaths(unique(c('/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.5','/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.4',.libPaths())))
suppressPackageStartupMessages({library(data.table);library(qs);library(Matrix);library(CellChat)})
root<-'/home/data/t070721/codex_workspace/Bladder Metabolism/mp10_subtype_screen_round1_v2';tt<-file.path(root,'tables');source(file.path(root,'scripts/fast_trimean.R'));setDTthreads(1);future::plan('sequential');options(future.globals.maxSize=20*1024^3)
s<-fread(file.path(tt,'samples_v2.tsv'));m<-fread(file.path(tt,'cells_v2.tsv.gz'));x<-qread(file.path(dirname(root),'mp10_subtype_screen_round1/objects/signaling_RNA_data.qs'),nthreads=1)
s[,epi_state_eligible:=tolower(as.character(epi_state_eligible))=='true'];m<-merge(m,s[,.(sample_uid,T_category,sample_MP10_group_allEpi,epi_state_eligible,n_Epi_MP10_low,n_Epi_MP10_high)],by='sample_uid',sort=FALSE);stopifnot(all(m$barcode%in%colnames(x)),!anyDuplicated(m$barcode));x<-x[,m$barcode];DB<-CellChatDB.human

s[,matched_B_Plasma:=epi_state_eligible & n_parent_B>=30 & n_parent_Plasma>=30];m<-merge(m,s[,.(sample_uid,matched_B_Plasma)],by='sample_uid',sort=FALSE);dir.create(file.path(root,'objects/networks_matched_B_Plasma'),showWarnings=FALSE)
fwrite(s[matched_B_Plasma==TRUE,.(sample_uid,dataset,patient_uid_recorded,n_parent_B,n_parent_Plasma)],file.path(tt,'matched_B_Plasma_sensitivity_specimens.tsv'),sep='\t')
tasks<-list();for(ds in c(sort(unique(m$dataset)),'ALL')){ids<-which((ds=='ALL'|m$dataset==ds)&m$matched_B_Plasma);if(length(ids))tasks[[length(tasks)+1]]<-list(scope=ds,comparison='epi_state_within_specimen',condition='shared',network_level='major',ids=ids)}
worker<-function(task){id<-paste(task$network_level,task$scope,task$comparison,task$condition,sep='__');fp<-file.path(root,'objects/networks_matched_B_Plasma',paste0(id,'.qs'));lf<-file.path(root,'logs',paste0('CellChat_matched_B_Plasma_',id,'.log'));if(file.exists(fp))return(data.table(network_id=id,status='reused'))
 sink(lf);on.exit(sink(),add=TRUE);tryCatch({md<-copy(m[task$ids]);md[,node:=if(task$network_level=='major')major else subtype];state<-task$comparison=='epi_state_within_specimen';if(state)md[major=='Epithelial',node:=epi_MP10_state_within_specimen]else md[major=='Epithelial',node:='Epithelial'];stopifnot(!anyNA(md$node),!anyDuplicated(md$barcode))
 rawcounts<-md[,.(n_raw=.N),by=.(dataset,sample_uid,patient_uid_recorded,node)];setorder(md,sample_uid,node,barcode);set.seed(123)
 md[,cap:=100L];if(state)md[major=='Epithelial',cap:=pmin(100L,n_Epi_MP10_low,n_Epi_MP10_high)]
 sel<-md[,.I[if(.N>cap[1])sample.int(.N,cap[1])else seq_len(.N)],by=.(sample_uid,node)]$V1;md<-md[sel];cnt<-md[,.N,by=node];keep<-cnt[N>=30,node];contrib<-merge(rawcounts,md[,.(n_sampled=.N),by=.(dataset,sample_uid,patient_uid_recorded,node)],all.x=TRUE);md<-md[node%in%keep];if(length(keep)<2)stop('fewer_than_two_nodes')
 if(state){ep<-md[node%in%c('Epi_MP10_low','Epi_MP10_high'),.N,by=.(sample_uid,node)];ep<-dcast(ep,sample_uid~node,value.var='N');stopifnot(all(ep$Epi_MP10_low==ep$Epi_MP10_high))}
 cat('START',id,format(Sys.time()),nrow(md),'cells',length(keep),'nodes\n');meta<-data.frame(labels=factor(md$node),row.names=md$barcode);cc<-createCellChat(x[,md$barcode],meta=meta,group.by='labels');cc@DB<-DB;cc<-subsetData(cc);cc<-identifyOverExpressedGenes(cc);cc<-identifyOverExpressedInteractions(cc);cc<-computeCommunProb_fast(cc,type='triMean',population.size=FALSE,raw.use=TRUE,nboot=100,seed.use=123);cc<-filterCommunication(cc,min.cells=30);cc<-computeCommunProbPathway(cc);cc<-aggregateNet(cc)
 obj<-list(net=cc@net,netP=cc@netP,LR=cc@LR$LRsig,counts=cnt,contributions=contrib,scope=task$scope,comparison_type=task$comparison,condition=task$condition,network_level=task$network_level,genes=rownames(cc@data.signaling),params=list(version=as.character(packageVersion('CellChat')),type='triMean',population.size=FALSE,raw.use=TRUE,nboot=100,seed=123,min.cells=30,cap=100,epi_equal_within_specimen=state,data_max=max(cc@data.signaling)))
 tmp<-paste0(fp,'.tmp');qsave(obj,tmp,preset='fast');file.rename(tmp,fp);cat('DONE',format(Sys.time()),'\n');data.table(network_id=id,status='completed',n_cells=nrow(md),n_nodes=length(keep),n_LR=nrow(cc@LR$LRsig))
 },error=function(e){cat('ERROR',conditionMessage(e),'\n');data.table(network_id=id,status='failed',reason=conditionMessage(e))})}

r<-parallel::mclapply(tasks,worker,mc.cores=3,mc.preschedule=FALSE);fwrite(rbindlist(r,fill=TRUE),file.path(tt,'matched_B_Plasma_network_status.tsv'),sep='\t');cat('MATCHED NETWORKS DONE\n')
